function spawn(){if(!S)return;mobs=[];if(ZONES[S.zone].safe)return;for(let i=0;i<6;i++){let [x,y]=SPAWN_POINTS[(i+S.zone*2)%SPAWN_POINTS.length];if(isBlocked(x,y))continue;let maxHp=36+S.zone*12+S.lv*5;mobs.push({x,y,homeX:x,homeY:y,hp:maxHp,maxHp,name:ZONES[S.zone].enemies[i%2],next:0,attack:0,animState:'idle',animStarted:now,animUntil:0,deadAt:0})}}
function loop(t){if(!S)return;let dt=Math.min((t-last)/1000||.016,.05);last=t;now=t/1000;update(dt);draw();requestAnimationFrame(loop)}
